//! Safe bindings to Roc's networkless pipeline: libroc 0.4's sender
//! encoder and receiver decoder. Roc has no official Rust bindings; the raw
//! ones are generated by bindgen against the system's libroc (Fedora's
//! `roc-toolkit-devel`).
//!
//! The encoder and decoder run Roc's whole pipeline (packetizing, FEC,
//! resampling, clock-drift compensation, loss repair, latency tuning) but
//! never touch a socket: an [`Encoder`] turns audio frames into packets the
//! caller carries however it likes, and a [`Decoder`] turns packets the
//! caller hands it back into frames. niox carries them inside its own
//! encrypted transport (see the `niox-audio` crate).
//!
//! # Interfaces
//!
//! A stream uses up to three packet [`Interface`]s: source (the audio
//! itself), repair (FEC redundancy, present only when FEC is on), and
//! control (RTCP, which flows both ways: reports from encoder to decoder,
//! and feedback from decoder to encoder). After every
//! [`Encoder::push_frame`] the caller pops packets from each of
//! [`Encoder::interfaces`] and delivers them to the same interface of the
//! remote decoder; after every [`Decoder::pop_frame`] it pops the decoder's
//! feedback and delivers it to the remote encoder's control interface.
//!
//! # Formats
//!
//! Frames are interleaved 32-bit floats at any rate. On the wire Roc uses
//! its built-in RTP payload types, 16-bit PCM at 44.1 kHz (mono or stereo
//! to match the frames), and converts the rate as needed on both ends.
//!
//! # Threads
//!
//! libroc documents its context, encoder, and decoder as safe to use
//! concurrently, so all three are `Send + Sync`: one thread can push
//! frames while another (e.g. the transport's receive thread) pushes
//! feedback packets.
//!
//! Roc's own log messages are forwarded to `tracing` under the `roc`
//! target.

#![allow(unsafe_code)] // FFI to libroc; every call is in this file.

mod sys;

use std::ffi::{CStr, c_void};
use std::ptr::{self, NonNull};
use std::sync::{Arc, Once};
use std::time::Duration;

/// Why a libroc call failed. libroc reports failure as a bare negative
/// return, so only the operation is known.
#[derive(Debug, thiserror::Error)]
#[non_exhaustive]
pub enum Error {
    /// libroc rejected the call (invalid arguments, an unsupported
    /// configuration, or allocation failure).
    #[error("{0} failed")]
    Call(&'static str),
    #[error("invalid configuration: {0}")]
    Config(&'static str),
    #[error("buffer of {have} bytes is smaller than the {need}-byte maximum packet")]
    BufferTooSmall { need: usize, have: usize },
    #[error("packet of {have} bytes exceeds the {max}-byte maximum")]
    PacketTooLarge { max: usize, have: usize },
    #[error("{samples} samples isn't a whole number of {channels}-channel frames")]
    PartialFrame { samples: usize, channels: usize },
}

fn check(ret: i32, op: &'static str) -> Result<(), Error> {
    if ret < 0 {
        Err(Error::Call(op))
    } else {
        Ok(())
    }
}

/// Channel layout of a stream.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Channels {
    Mono,
    Stereo,
}

impl Channels {
    pub fn count(self) -> usize {
        match self {
            Self::Mono => 1,
            Self::Stereo => 2,
        }
    }

    fn layout(self) -> sys::roc_channel_layout {
        match self {
            Self::Mono => sys::ROC_CHANNEL_LAYOUT_MONO,
            Self::Stereo => sys::ROC_CHANNEL_LAYOUT_STEREO,
        }
    }

    fn packet_encoding(self) -> sys::roc_packet_encoding {
        match self {
            Self::Mono => sys::ROC_PACKET_ENCODING_AVP_L16_MONO,
            Self::Stereo => sys::ROC_PACKET_ENCODING_AVP_L16_STEREO,
        }
    }
}

/// The local side of a stream: interleaved 32-bit float frames.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Format {
    pub rate: u32,
    pub channels: Channels,
}

impl Format {
    fn encoding(self) -> sys::roc_media_encoding {
        sys::roc_media_encoding {
            rate: self.rate,
            format: sys::ROC_FORMAT_PCM_FLOAT32,
            channels: self.channels.layout(),
            tracks: 0,
        }
    }
}

/// The sample rate of every packet on the wire (the built-in L16 RTP
/// payload types).
pub const WIRE_RATE: u32 = 44_100;

/// Forward error correction. Encoder and decoder must agree.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Fec {
    /// No repair packets; a lost packet is concealed, not recovered.
    Disabled,
    /// Reed-Solomon (m=8), Roc's default: blocks of up to 255 packets.
    /// Zero block sizes pick Roc's defaults.
    Rs8m { source: u32, repair: u32 },
    /// LDPC-Staircase: cheaper on large blocks.
    LdpcStaircase { source: u32, repair: u32 },
}

impl Default for Fec {
    fn default() -> Self {
        Self::Rs8m {
            source: 0,
            repair: 0,
        }
    }
}

impl Fec {
    fn encoding(self) -> sys::roc_fec_encoding {
        match self {
            Self::Disabled => sys::ROC_FEC_ENCODING_DISABLE,
            Self::Rs8m { .. } => sys::ROC_FEC_ENCODING_RS8M,
            Self::LdpcStaircase { .. } => sys::ROC_FEC_ENCODING_LDPC_STAIRCASE,
        }
    }

    fn block(self) -> (u32, u32) {
        match self {
            Self::Disabled => (0, 0),
            Self::Rs8m { source, repair } | Self::LdpcStaircase { source, repair } => {
                (source, repair)
            }
        }
    }

    /// The protocol for each interface this FEC scheme uses.
    fn protocols(self) -> &'static [(Interface, sys::roc_protocol)] {
        match self {
            Self::Disabled => &[
                (Interface::Source, sys::ROC_PROTO_RTP),
                (Interface::Control, sys::ROC_PROTO_RTCP),
            ],
            Self::Rs8m { .. } => &[
                (Interface::Source, sys::ROC_PROTO_RTP_RS8M_SOURCE),
                (Interface::Repair, sys::ROC_PROTO_RS8M_REPAIR),
                (Interface::Control, sys::ROC_PROTO_RTCP),
            ],
            Self::LdpcStaircase { .. } => &[
                (Interface::Source, sys::ROC_PROTO_RTP_LDPC_SOURCE),
                (Interface::Repair, sys::ROC_PROTO_LDPC_REPAIR),
                (Interface::Control, sys::ROC_PROTO_RTCP),
            ],
        }
    }
}

/// Who paces the stream.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Clock {
    /// The caller pushes and pops at the audio rate itself (e.g. driven by
    /// a sound card); calls never block.
    External,
    /// libroc paces the caller: [`Encoder::push_frame`] and
    /// [`Decoder::pop_frame`] block until the frame is due.
    Internal,
}

impl Clock {
    fn source(self) -> sys::roc_clock_source {
        match self {
            Self::External => sys::ROC_CLOCK_SOURCE_EXTERNAL,
            Self::Internal => sys::ROC_CLOCK_SOURCE_INTERNAL,
        }
    }
}

/// One of a stream's packet interfaces (see the crate docs).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Interface {
    Source,
    Repair,
    Control,
}

impl Interface {
    fn raw(self) -> sys::roc_interface {
        match self {
            Self::Source => sys::ROC_INTERFACE_AUDIO_SOURCE,
            Self::Repair => sys::ROC_INTERFACE_AUDIO_REPAIR,
            Self::Control => sys::ROC_INTERFACE_AUDIO_CONTROL,
        }
    }
}

fn nanos(duration: Duration) -> u64 {
    u64::try_from(duration.as_nanos()).unwrap_or(u64::MAX)
}

#[derive(Debug)]
struct ContextInner {
    raw: NonNull<sys::roc_context>,
    max_packet: usize,
}

// SAFETY: libroc documents roc_context as safe to use concurrently.
unsafe impl Send for ContextInner {}
// SAFETY: as above.
unsafe impl Sync for ContextInner {}

impl Drop for ContextInner {
    fn drop(&mut self) {
        // Every encoder and decoder holds a clone of the Arc, so none is
        // still attached.
        // SAFETY: raw came from roc_context_open and is closed only here.
        let ret = unsafe { sys::roc_context_close(self.raw.as_ptr()) };
        if ret < 0 {
            tracing::error!("roc_context_close failed");
        }
    }
}

/// A libroc context: shared buffer pools and background threads. Cheap to
/// clone; it stays open until its last clone, encoder, and decoder are
/// dropped.
#[derive(Debug, Clone)]
pub struct Context(Arc<ContextInner>);

impl Context {
    /// Opens a context whose packets are at most `max_packet` bytes.
    /// Encoders must be configured so every packet fits.
    pub fn new(max_packet: usize) -> Result<Self, Error> {
        init_logging();
        let config = sys::roc_context_config {
            max_packet_size: u32::try_from(max_packet)
                .map_err(|_| Error::Config("max_packet is too large"))?,
            max_frame_size: 0,
        };
        let mut raw = ptr::null_mut();
        // SAFETY: config is a valid, initialized struct; raw is an out
        // pointer.
        check(
            unsafe { sys::roc_context_open(&config, &mut raw) },
            "roc_context_open",
        )?;
        let raw = NonNull::new(raw).ok_or(Error::Call("roc_context_open"))?;
        Ok(Self(Arc::new(ContextInner { raw, max_packet })))
    }

    /// The largest packet this context handles.
    pub fn max_packet(&self) -> usize {
        self.0.max_packet
    }
}

/// Sends a stream: what [`Encoder::new`] needs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EncoderConfig {
    pub frame: Format,
    /// Audio per packet. Every packet must fit the context's maximum.
    pub packet_length: Duration,
    pub fec: Fec,
    pub clock: Clock,
}

/// Bytes a packet carries besides its samples, rounded up: the RTP header
/// (12), the FEC source footer (6), or a repair packet's larger FEC header
/// (up to 20 measured).
const PACKET_OVERHEAD: usize = 32;

impl EncoderConfig {
    /// An upper bound on the size of the packets this configuration
    /// produces. [`Encoder::new`] refuses a configuration where this
    /// exceeds [`Context::max_packet`], since libroc silently drops packets
    /// that don't fit.
    pub fn max_packet_size(&self) -> usize {
        let samples =
            (u128::from(WIRE_RATE) * self.packet_length.as_nanos()).div_ceil(1_000_000_000);
        let samples = usize::try_from(samples).unwrap_or(usize::MAX);
        samples
            .saturating_mul(self.frame.channels.count() * 2)
            .saturating_add(PACKET_OVERHEAD)
    }
}

/// Turns audio frames into packets.
#[derive(Debug)]
pub struct Encoder {
    raw: NonNull<sys::roc_sender_encoder>,
    interfaces: Vec<Interface>,
    channels: usize,
    context: Context,
}

// SAFETY: libroc documents roc_sender_encoder as safe to use concurrently.
unsafe impl Send for Encoder {}
// SAFETY: as above.
unsafe impl Sync for Encoder {}

impl Encoder {
    pub fn new(context: &Context, config: &EncoderConfig) -> Result<Self, Error> {
        if config.packet_length.is_zero() {
            return Err(Error::Config("packet_length must be positive"));
        }
        if config.max_packet_size() > context.max_packet() {
            return Err(Error::Config(
                "packet_length is too long for the context's maximum packet",
            ));
        }
        let (source, repair) = config.fec.block();
        // SAFETY: roc_sender_config is a flat struct whose zero value means
        // "default" for every field (documented in config.h).
        let mut raw_config: sys::roc_sender_config = unsafe { std::mem::zeroed() };
        raw_config.frame_encoding = config.frame.encoding();
        raw_config.packet_encoding = config.frame.channels.packet_encoding();
        raw_config.packet_length = nanos(config.packet_length);
        raw_config.fec_encoding = config.fec.encoding();
        raw_config.fec_block_source_packets = source;
        raw_config.fec_block_repair_packets = repair;
        raw_config.clock_source = config.clock.source();

        let mut raw = ptr::null_mut();
        // SAFETY: the context is open (we hold a reference); raw_config is
        // initialized; raw is an out pointer.
        check(
            unsafe { sys::roc_sender_encoder_open(context.0.raw.as_ptr(), &raw_config, &mut raw) },
            "roc_sender_encoder_open",
        )?;
        let raw = NonNull::new(raw).ok_or(Error::Call("roc_sender_encoder_open"))?;
        let mut encoder = Self {
            raw,
            interfaces: Vec::new(),
            channels: config.frame.channels.count(),
            context: context.clone(),
        };
        for &(iface, proto) in config.fec.protocols() {
            // SAFETY: the encoder is open.
            check(
                unsafe { sys::roc_sender_encoder_activate(raw.as_ptr(), iface.raw(), proto) },
                "roc_sender_encoder_activate",
            )?;
            encoder.interfaces.push(iface);
        }
        Ok(encoder)
    }

    /// The interfaces this encoder produces packets on.
    pub fn interfaces(&self) -> &[Interface] {
        &self.interfaces
    }

    /// Encodes interleaved samples into packets, queued per interface.
    /// With [`Clock::Internal`], blocks until the samples are due.
    pub fn push_frame(&self, samples: &[f32]) -> Result<(), Error> {
        whole_frames(samples.len(), self.channels)?;
        let frame = sys::roc_frame {
            samples: samples.as_ptr().cast_mut().cast::<c_void>(),
            samples_size: size_of_val(samples),
        };
        // SAFETY: the encoder is open; frame points at samples, which
        // outlive the call, and libroc only reads (copies) them.
        check(
            unsafe { sys::roc_sender_encoder_push_frame(self.raw.as_ptr(), &frame) },
            "roc_sender_encoder_push_frame",
        )
    }

    /// Takes the next queued packet for `iface` into `buf`, which must hold
    /// at least [`Context::max_packet`] bytes. `None` once the queue is
    /// empty.
    pub fn pop_packet<'b>(
        &self,
        iface: Interface,
        buf: &'b mut [u8],
    ) -> Result<Option<&'b [u8]>, Error> {
        // SAFETY: the encoder is open; pop_into upholds the buffer contract.
        pop_into(self.context.max_packet(), buf, |packet| unsafe {
            sys::roc_sender_encoder_pop_packet(self.raw.as_ptr(), iface.raw(), packet)
        })
    }

    /// Delivers a feedback packet from the remote decoder's control
    /// interface.
    pub fn push_feedback(&self, packet: &[u8]) -> Result<(), Error> {
        // SAFETY: the encoder is open; push_from upholds the buffer
        // contract.
        push_from(
            self.context.max_packet(),
            packet,
            "roc_sender_encoder_push_feedback_packet",
            |p| unsafe {
                sys::roc_sender_encoder_push_feedback_packet(
                    self.raw.as_ptr(),
                    Interface::Control.raw(),
                    p,
                )
            },
        )
    }

    /// End-to-end latency as last reported by the decoder's feedback, if
    /// any has arrived.
    pub fn latency(&self) -> Option<Duration> {
        let mut metrics = sys::roc_sender_metrics {
            connection_count: 0,
        };
        let mut conn = sys::roc_connection_metrics { e2e_latency: 0 };
        // SAFETY: the encoder is open; both are valid out structs.
        let ret =
            unsafe { sys::roc_sender_encoder_query(self.raw.as_ptr(), &mut metrics, &mut conn) };
        (ret >= 0 && metrics.connection_count > 0 && conn.e2e_latency > 0)
            .then(|| Duration::from_nanos(conn.e2e_latency))
    }
}

impl Drop for Encoder {
    fn drop(&mut self) {
        // SAFETY: raw came from roc_sender_encoder_open and is closed only
        // here; &mut self means no other call is in flight.
        if unsafe { sys::roc_sender_encoder_close(self.raw.as_ptr()) } < 0 {
            tracing::error!("roc_sender_encoder_close failed");
        }
    }
}

/// Receives a stream: what [`Decoder::new`] needs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct DecoderConfig {
    pub frame: Format,
    pub fec: Fec,
    pub clock: Clock,
    /// Latency the decoder's tuner aims for. `None` picks Roc's default.
    pub target_latency: Option<Duration>,
}

/// Turns packets back into audio frames.
#[derive(Debug)]
pub struct Decoder {
    raw: NonNull<sys::roc_receiver_decoder>,
    interfaces: Vec<Interface>,
    channels: usize,
    context: Context,
}

// SAFETY: libroc documents roc_receiver_decoder as safe to use
// concurrently.
unsafe impl Send for Decoder {}
// SAFETY: as above.
unsafe impl Sync for Decoder {}

impl Decoder {
    pub fn new(context: &Context, config: &DecoderConfig) -> Result<Self, Error> {
        // SAFETY: roc_receiver_config is a flat struct whose zero value
        // means "default" for every field (documented in config.h).
        let mut raw_config: sys::roc_receiver_config = unsafe { std::mem::zeroed() };
        raw_config.frame_encoding = config.frame.encoding();
        raw_config.clock_source = config.clock.source();
        raw_config.target_latency = config.target_latency.map_or(0, nanos);

        let mut raw = ptr::null_mut();
        // SAFETY: the context is open (we hold a reference); raw_config is
        // initialized; raw is an out pointer.
        check(
            unsafe {
                sys::roc_receiver_decoder_open(context.0.raw.as_ptr(), &raw_config, &mut raw)
            },
            "roc_receiver_decoder_open",
        )?;
        let raw = NonNull::new(raw).ok_or(Error::Call("roc_receiver_decoder_open"))?;
        let mut decoder = Self {
            raw,
            interfaces: Vec::new(),
            channels: config.frame.channels.count(),
            context: context.clone(),
        };
        for &(iface, proto) in config.fec.protocols() {
            // SAFETY: the decoder is open.
            check(
                unsafe { sys::roc_receiver_decoder_activate(raw.as_ptr(), iface.raw(), proto) },
                "roc_receiver_decoder_activate",
            )?;
            decoder.interfaces.push(iface);
        }
        Ok(decoder)
    }

    /// The interfaces this decoder accepts packets on.
    pub fn interfaces(&self) -> &[Interface] {
        &self.interfaces
    }

    /// Queues a packet from the remote encoder's `iface`. It's consumed by
    /// the next [`pop_frame`](Self::pop_frame).
    pub fn push_packet(&self, iface: Interface, packet: &[u8]) -> Result<(), Error> {
        // SAFETY: the decoder is open; push_from upholds the buffer
        // contract.
        push_from(
            self.context.max_packet(),
            packet,
            "roc_receiver_decoder_push_packet",
            |p| unsafe { sys::roc_receiver_decoder_push_packet(self.raw.as_ptr(), iface.raw(), p) },
        )
    }

    /// Fills `samples` (interleaved) with decoded audio, or silence where
    /// nothing has arrived. With [`Clock::Internal`], blocks until the
    /// samples are due.
    pub fn pop_frame(&self, samples: &mut [f32]) -> Result<(), Error> {
        whole_frames(samples.len(), self.channels)?;
        let mut frame = sys::roc_frame {
            samples: samples.as_mut_ptr().cast::<c_void>(),
            samples_size: size_of_val(samples),
        };
        // SAFETY: the decoder is open; frame points at samples, which
        // libroc fills completely and which outlive the call.
        check(
            unsafe { sys::roc_receiver_decoder_pop_frame(self.raw.as_ptr(), &mut frame) },
            "roc_receiver_decoder_pop_frame",
        )
    }

    /// Takes the next queued feedback packet into `buf`, which must hold at
    /// least [`Context::max_packet`] bytes. `None` once the queue is empty.
    pub fn pop_feedback<'b>(&self, buf: &'b mut [u8]) -> Result<Option<&'b [u8]>, Error> {
        // SAFETY: the decoder is open; pop_into upholds the buffer contract.
        pop_into(self.context.max_packet(), buf, |packet| unsafe {
            sys::roc_receiver_decoder_pop_feedback_packet(
                self.raw.as_ptr(),
                Interface::Control.raw(),
                packet,
            )
        })
    }

    /// Whether a sender is currently connected, and the end-to-end latency
    /// once known.
    pub fn connection(&self) -> Option<Option<Duration>> {
        let mut metrics = sys::roc_receiver_metrics {
            connection_count: 0,
        };
        let mut conn = sys::roc_connection_metrics { e2e_latency: 0 };
        // SAFETY: the decoder is open; both are valid out structs.
        let ret =
            unsafe { sys::roc_receiver_decoder_query(self.raw.as_ptr(), &mut metrics, &mut conn) };
        (ret >= 0 && metrics.connection_count > 0)
            .then(|| (conn.e2e_latency > 0).then(|| Duration::from_nanos(conn.e2e_latency)))
    }
}

impl Drop for Decoder {
    fn drop(&mut self) {
        // SAFETY: raw came from roc_receiver_decoder_open and is closed
        // only here; &mut self means no other call is in flight.
        if unsafe { sys::roc_receiver_decoder_close(self.raw.as_ptr()) } < 0 {
            tracing::error!("roc_receiver_decoder_close failed");
        }
    }
}

fn whole_frames(samples: usize, channels: usize) -> Result<(), Error> {
    if samples.is_multiple_of(channels) {
        Ok(())
    } else {
        Err(Error::PartialFrame { samples, channels })
    }
}

/// Pops one packet through `pop` into `buf`. libroc returns the same
/// negative value for "queue empty" and "buffer too small", so the buffer
/// is checked against the context's maximum first and a failure then
/// means "empty".
fn pop_into(
    max_packet: usize,
    buf: &mut [u8],
    pop: impl FnOnce(*mut sys::roc_packet) -> i32,
) -> Result<Option<&[u8]>, Error> {
    if buf.len() < max_packet {
        return Err(Error::BufferTooSmall {
            need: max_packet,
            have: buf.len(),
        });
    }
    let mut packet = sys::roc_packet {
        bytes: buf.as_mut_ptr().cast::<c_void>(),
        bytes_size: buf.len(),
    };
    if pop(&mut packet) < 0 {
        return Ok(None);
    }
    Ok(buf.get(..packet.bytes_size))
}

/// Pushes `bytes` through `push` as a packet libroc copies.
fn push_from(
    max_packet: usize,
    bytes: &[u8],
    op: &'static str,
    push: impl FnOnce(*const sys::roc_packet) -> i32,
) -> Result<(), Error> {
    if bytes.len() > max_packet {
        return Err(Error::PacketTooLarge {
            max: max_packet,
            have: bytes.len(),
        });
    }
    let packet = sys::roc_packet {
        bytes: bytes.as_ptr().cast_mut().cast::<c_void>(),
        bytes_size: bytes.len(),
    };
    check(push(&packet), op)
}

/// Routes libroc's log to `tracing` (once per process), at a level
/// matching tracing's current maximum.
fn init_logging() {
    static ONCE: Once = Once::new();
    ONCE.call_once(|| {
        use tracing::level_filters::LevelFilter;
        let level = match LevelFilter::current() {
            LevelFilter::TRACE => sys::ROC_LOG_TRACE,
            LevelFilter::DEBUG => sys::ROC_LOG_DEBUG,
            LevelFilter::INFO => sys::ROC_LOG_INFO,
            LevelFilter::OFF => sys::ROC_LOG_NONE,
            _ => sys::ROC_LOG_ERROR,
        };
        // SAFETY: log_handler matches roc_log_handler and is valid for the
        // life of the process; it ignores the (null) argument.
        unsafe {
            sys::roc_log_set_level(level);
            sys::roc_log_set_handler(Some(log_handler), ptr::null_mut());
        }
    });
}

unsafe extern "C" fn log_handler(message: *const sys::roc_log_message, _arg: *mut c_void) {
    // SAFETY: libroc passes a valid message for the duration of the call.
    let Some(message) = (unsafe { message.as_ref() }) else {
        return;
    };
    let text = |s: *const std::ffi::c_char| {
        if s.is_null() {
            std::borrow::Cow::Borrowed("")
        } else {
            // SAFETY: libroc's strings are NUL-terminated and live for the
            // call.
            unsafe { CStr::from_ptr(s) }.to_string_lossy()
        }
    };
    let module = text(message.module);
    let body = text(message.text);
    match message.level {
        sys::ROC_LOG_ERROR => tracing::error!(target: "roc", %module, "{body}"),
        sys::ROC_LOG_INFO => tracing::info!(target: "roc", %module, "{body}"),
        sys::ROC_LOG_NOTE | sys::ROC_LOG_DEBUG => {
            tracing::debug!(target: "roc", %module, "{body}");
        }
        _ => tracing::trace!(target: "roc", %module, "{body}"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const RATE: u32 = 48_000;
    const MAX_PACKET: usize = 1246;

    fn configs(fec: Fec, latency: Duration) -> (EncoderConfig, DecoderConfig) {
        let frame = Format {
            rate: RATE,
            channels: Channels::Stereo,
        };
        (
            EncoderConfig {
                frame,
                packet_length: Duration::from_millis(5),
                fec,
                clock: Clock::External,
            },
            DecoderConfig {
                frame,
                fec,
                clock: Clock::External,
                target_latency: Some(latency),
            },
        )
    }

    /// 10ms of a stereo tone (left `freq`, right twice that), starting at
    /// sample `start`.
    fn tone(freq: f32, start: usize) -> Vec<f32> {
        let n = RATE as usize / 100;
        (start..start + n)
            .flat_map(|i| {
                let t = i as f32 / RATE as f32;
                let l = 0.5 * (std::f32::consts::TAU * freq * t).sin();
                let r = 0.5 * (std::f32::consts::TAU * 2.0 * freq * t).sin();
                [l, r]
            })
            .collect()
    }

    /// Streams 4s of tone from an encoder to a decoder in memory, dropping
    /// the source packets `drop_source` picks (by 1-based count), and
    /// returns the decoded audio after the first second, once it has
    /// settled.
    fn stream(fec: Fec, latency: Duration, mut drop_source: impl FnMut(usize) -> bool) -> Vec<f32> {
        let context = Context::new(MAX_PACKET).unwrap();
        let (enc_config, dec_config) = configs(fec, latency);
        let encoder = Encoder::new(&context, &enc_config).unwrap();
        let decoder = Decoder::new(&context, &dec_config).unwrap();
        let mut buf = vec![0u8; MAX_PACKET];
        let mut out = vec![0f32; RATE as usize / 100 * 2];
        let mut decoded = Vec::new();
        let mut sources = 0;
        for chunk in 0..400 {
            encoder.push_frame(&tone(440.0, chunk * 480)).unwrap();
            for &iface in encoder.interfaces() {
                while let Some(packet) = encoder.pop_packet(iface, &mut buf).unwrap() {
                    assert!(packet.len() <= enc_config.max_packet_size());
                    if iface == Interface::Source {
                        sources += 1;
                        if drop_source(sources) {
                            continue;
                        }
                    }
                    decoder.push_packet(iface, packet).unwrap();
                }
            }
            decoder.pop_frame(&mut out).unwrap();
            while let Some(packet) = decoder.pop_feedback(&mut buf).unwrap() {
                encoder.push_feedback(packet).unwrap();
            }
            // Skip the first second: the decoder outputs silence until its
            // latency target fills.
            if chunk >= 100 {
                decoded.extend_from_slice(&out);
            }
        }
        decoded
    }

    /// Frequency of one channel by counting rising zero crossings.
    fn frequency(samples: &[f32], channel: usize) -> f32 {
        let ch: Vec<f32> = samples.iter().skip(channel).step_by(2).copied().collect();
        let crossings = ch.windows(2).filter(|w| w[0] < 0.0 && w[1] >= 0.0).count();
        crossings as f32 * RATE as f32 / ch.len() as f32
    }

    fn rms(samples: &[f32]) -> f32 {
        (samples.iter().map(|s| s * s).sum::<f32>() / samples.len() as f32).sqrt()
    }

    #[test]
    fn tone_survives_the_pipeline() {
        for fec in [
            Fec::Disabled,
            Fec::default(),
            Fec::LdpcStaircase {
                source: 0,
                repair: 0,
            },
        ] {
            let out = stream(fec, Duration::from_millis(40), |_| false);
            assert!(
                (rms(&out) - 0.5 / 2f32.sqrt()).abs() < 0.05,
                "{fec:?}: rms {}",
                rms(&out)
            );
            assert!((frequency(&out, 0) - 440.0).abs() < 5.0, "{fec:?}");
            assert!((frequency(&out, 1) - 880.0).abs() < 10.0, "{fec:?}");
        }
    }

    /// 1ms stretches of near-silence in a decoded tone.
    fn gaps(out: &[f32]) -> usize {
        out.chunks(96).filter(|chunk| rms(chunk) < 0.05).count()
    }

    #[test]
    fn fec_repairs_lost_source_packets() {
        // Repairs arrive with the end of a block, so the latency target
        // must cover one (RS8M's default block is 18 packets, 90ms here).
        let latency = Duration::from_millis(200);
        let lossy = |n: usize| n.is_multiple_of(10);
        assert!(gaps(&stream(Fec::Disabled, latency, lossy)) > 0);
        assert_eq!(gaps(&stream(Fec::default(), latency, lossy)), 0);
    }

    #[test]
    fn buffers_are_checked() {
        let context = Context::new(MAX_PACKET).unwrap();
        let (enc_config, dec_config) = configs(Fec::Disabled, Duration::from_millis(40));
        let encoder = Encoder::new(&context, &enc_config).unwrap();
        let decoder = Decoder::new(&context, &dec_config).unwrap();
        let mut small = [0u8; 100];
        assert!(matches!(
            encoder.pop_packet(Interface::Source, &mut small),
            Err(Error::BufferTooSmall { .. })
        ));
        assert!(matches!(
            decoder.push_packet(Interface::Source, &[0; MAX_PACKET + 1]),
            Err(Error::PacketTooLarge { .. })
        ));
        // Garbage is accepted into the queue and dropped by the pipeline.
        assert!(matches!(
            encoder.push_frame(&[0.0; 3]),
            Err(Error::PartialFrame { .. })
        ));
        decoder.push_packet(Interface::Source, &[0xff; 64]).unwrap();
        let mut out = vec![1f32; 960];
        decoder.pop_frame(&mut out).unwrap();
        assert!(out.iter().all(|&s| s == 0.0));
    }

    #[test]
    fn packets_that_cannot_fit_are_refused() {
        let context = Context::new(MAX_PACKET).unwrap();
        let (mut config, _) = configs(Fec::Disabled, Duration::from_millis(40));
        // 5ms of 44.1 kHz stereo is 221 frames, 884 bytes: fits.
        assert!(config.max_packet_size() <= MAX_PACKET);
        // 20ms is 3528 bytes. libroc would accept it and drop every packet.
        config.packet_length = Duration::from_millis(20);
        assert!(matches!(
            Encoder::new(&context, &config),
            Err(Error::Config(_))
        ));
        config.packet_length = Duration::ZERO;
        assert!(matches!(
            Encoder::new(&context, &config),
            Err(Error::Config(_))
        ));
    }
}
